/* Generated by tools/build_lines.py from picks/d.txt. Every line is from: NCERT XII (2026-27) Unit 4. Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("d", "NCERT XII (2026-27) Unit 4", [{"sec": "Position and electronic configuration","ids": [1],"t": "d-block: groups 3–12; d orbitals progressively filled in the four long periods.","exc": false,"tab": false,"src": "d","page": 1,"o": "The d-block of the periodic table contains the elements of the groups 3-12 in which the d orbitals are progressively filled in each of the four long periods."},{"sec": "Position and electronic configuration","ids": [5],"t": "Four series: 3d (Sc–Zn), 4d (Y–Cd), 5d (La, Hf–Hg), 6d (Ac, Rf–Cn).","exc": false,"tab": false,"src": "d","page": 1,"o": "There are mainly four series of the transition metals, 3d series (Sc to Zn), 4d series (Y to Cd), 5d series (La and Hf to Hg) and 6d series which has Ac and elements from Rf to Cn."},{"sec": "Position and electronic configuration","ids": [7],"t": "IUPAC: transition metal = incomplete d subshell in the neutral atom or in its ions.","exc": false,"tab": false,"src": "d","page": 1,"o": "Now according to IUPAC, transition metals are defined as metals which have incomplete d subshell either in neutral atom or in their ions."},{"sec": "Position and electronic configuration","ids": [8],"t": "**Zn, Cd, Hg: d^10 in ground state and in common oxidation states, so not transition metals.**","exc": true,"tab": false,"src": "d","page": 1,"o": "Zinc, cadmium and mercury of group 12 have full d^10 configuration in their ground state as well as in their common oxidation states and hence, are not regarded as transition metals."},{"sec": "Position and electronic configuration","ids": [23],"t": "General outer configuration (n–1)d^1–10 ns^1–2; **exception Pd: 4d^10 5s^0.**","exc": true,"tab": false,"src": "d","page": 2,"o": "In general the electronic configuration of outer orbitals of these elements is (n-1)d^1–10 ns^1–2 except for Pd where its electronic configuration is 4d^10 5s^0."},{"sec": "Position and electronic configuration","ids": [24],"t": "(n–1)d holds 1–10 electrons; outer ns holds 1 or 2.","exc": false,"tab": false,"src": "d","page": 2,"o": "The (n–1) stands for the inner d orbitals which may have one to ten electrons and the outermost ns orbital may have one or two electrons."},{"sec": "Position and electronic configuration","ids": [25],"t": "Many exceptions, because (n–1)d and ns are very close in energy.","exc": false,"tab": false,"src": "d","page": 2,"o": "However, this generalisation has several exceptions because of very little energy difference between (n-1)d and ns orbitals."},{"sec": "Position and electronic configuration","ids": [26],"t": "Half-filled and completely filled sets are extra stable.","exc": false,"tab": false,"src": "d","page": 2,"o": "Furthermore, half and completely filled sets of orbitals are relatively more stable."},{"sec": "Position and electronic configuration","ids": [27],"t": "This shows up in Cr and Cu (3d series).","exc": false,"tab": false,"src": "d","page": 2,"o": "A consequence of this factor is reflected in the electronic configurations of Cr and Cu in the 3d series."},{"sec": "Position and electronic configuration","ids": [28],"t": "**Cr: 3d^5 4s^1, not 3d^4 4s^2** (3d–4s gap small).","exc": true,"tab": false,"src": "d","page": 2,"o": "For example, consider the case of Cr, which has 3d^5 4s^1 configuration instead of 3d^4 4s^2; the energy gap between the two sets (3d and 4s) of orbitals is small enough to prevent electron entering the 3d orbitals."},{"sec": "Position and electronic configuration","ids": [29],"t": "**Cu: 3d^10 4s^1, not 3d^9 4s^2.**","exc": true,"tab": false,"src": "d","page": 2,"o": "Similarly in case of Cu, the configuration is 3d^10 4s^1 and not 3d^9 4s^2."},{"sec": "Position and electronic configuration","ids": [31,32,33],"t": "Zn, Cd, Hg, Cn: (n–1)d^10 ns^2; filled in ground and common oxidation states, so not transition elements.","exc": false,"tab": false,"src": "d","page": 3,"o": "The electronic configurations of outer orbitals of Zn, Cd, Hg and Cn are represented by the general formula (n-1)d ns . The orbitals in these elements are completely filled in the ground state as well as in their common oxidation states. Therefore, they are not regarded as transition elements."},{"sec": "Position and electronic configuration","ids": [34],"t": "d orbitals protrude to the periphery more than s and p: more influenced by, and more influence on, the surroundings.","exc": false,"tab": false,"src": "d","page": 3,"o": "The d orbitals of the transition elements protrude to the periphery of an atom more than the other orbitals (i.e., s and p), hence, they are more influenced by the surroundings as well as affect the atoms or molecules surrounding them."},{"sec": "Position and electronic configuration","ids": [35],"t": "Ions of the same d^n (n = 1–9) have similar magnetic and electronic properties.","exc": false,"tab": false,"src": "d","page": 3,"o": "In some respects, ions of a given d n configuration (n = 1 – 9) have similar magnetic and electronic properties."},{"sec": "Position and electronic configuration","ids": [36],"t": "Partly filled d → variety of oxidation states, coloured ions, complex formation with many ligands.","exc": false,"tab": false,"src": "d","page": 3,"o": "With partly filled d orbitals these elements exhibit certain characteristic properties such as display of a variety of oxidation states, formation of coloured ions and entering into complex formation with a variety of ligands."},{"sec": "Position and electronic configuration","ids": [37],"t": "Also catalytic activity and paramagnetism.","exc": false,"tab": false,"src": "d","page": 3,"o": "The transition metals and their compounds also exhibit catalytic property and paramagnetic behaviour."},{"sec": "Position and electronic configuration","ids": [39],"t": "Horizontal similarities across a row are greater than for non-transition elements.","exc": false,"tab": false,"src": "d","page": 3,"o": "There are greater similarities in the properties of the transition elements of a horizontal row in contrast to the non-transition elements."},{"sec": "Position and electronic configuration","ids": [41],"t": "Sc (3d^1 in ground state) counts as a transition element.","exc": false,"tab": false,"src": "d","page": 3,"o": "On the basis of incompletely filled 3d orbitals in case of scandium atom in its ground state (3d^1), it is regarded as a transition element."},{"sec": "Position and electronic configuration","ids": [42],"t": "Zn (3d^10 in atom and ion) does not.","exc": false,"tab": false,"src": "d","page": 3,"o": "On the other hand, zinc atom has completely filled d orbitals (3d ) in its ground state as well as in its oxidised state, hence it is not regarded as a transition element."},{"sec": "Position and electronic configuration","ids": [430],"t": "Ag (Z = 47) is transition: Ag(+2) has 4d^9.","exc": false,"tab": false,"src": "d","page": 29,"o": "Silver (Z = 47) can exhibit +2 oxidation state wherein it will have incompletely filled d-orbitals (4d^9), hence a transition element."},{"sec": "Physical properties","ids": [45],"t": "Typical metals: high tensile strength, ductile, malleable, high thermal and electrical conductivity, lustre.","exc": false,"tab": false,"src": "d","page": 4,"o": "Nearly all the transition elements display typical metallic properties such as high tensile strength, ductility, malleability, high thermal and electrical conductivity and metallic lustre."},{"sec": "Physical properties","ids": [46],"t": "**Except Zn, Cd, Hg and Mn,** they have one or more typical metallic structures at normal temperature.","exc": true,"tab": false,"src": "d","page": 4,"o": "With the exceptions of Zn, Cd, Hg and Mn, they have one or more typical metallic structures at normal temperatures."},{"sec": "Physical properties","ids": [47],"t": "Very hard, low volatility (**except Zn, Cd, Hg**).","exc": false,"tab": false,"src": "d","page": 4,"o": "The transition metals (with the exception of Zn, Cd and Hg) are very hard and have low volatility."},{"sec": "Physical properties","ids": [48],"t": "High m.p. and b.p.","exc": false,"tab": false,"src": "d","page": 4,"o": "Their melting and boiling points are high."},{"sec": "Physical properties","ids": [50],"t": "High m.p.: (n–1)d electrons join ns electrons in metallic bonding.","exc": false,"tab": false,"src": "d","page": 4,"o": "The high melting points of these metals are attributed to the involvement of greater number of electrons from (n-1)d in addition to the ns electrons in the interatomic metallic bonding."},{"sec": "Physical properties","ids": [51],"t": "m.p. rises to a maximum at d^5 then falls regularly, **except anomalous Mn and Tc.**","exc": true,"tab": false,"src": "d","page": 4,"o": "In any row the melting points of these metals rise to a maximum at d^5 except for anomalous values of Mn and Tc and fall regularly as the atomic number increases."},{"sec": "Physical properties","ids": [52],"t": "High enthalpies of atomisation (Fig. 4.2).","exc": false,"tab": false,"src": "d","page": 4,"o": "They have high enthalpies of atomisation which are shown in Fig. 4.2."},{"sec": "Physical properties","ids": [53,54],"t": "Maxima near mid-series: one unpaired electron per d orbital favours strong interatomic interaction.","exc": false,"tab": false,"src": "d","page": 4,"o": "The maxima at about the middle of each series indicate that one unpaired electron per d orbital is particularly favourable for strong interatomic interaction."},{"sec": "Physical properties","ids": [55],"t": "More valence electrons → stronger bonding.","exc": false,"tab": false,"src": "d","page": 5,"o": "In general, greater the number of valence electrons, stronger is the resultant bonding."},{"sec": "Physical properties","ids": [56],"t": "Very high ∆aH (very high b.p.) → metal tends to be noble (∆aH feeds into E°).","exc": false,"tab": false,"src": "d","page": 5,"o": "Since the enthalpy of atomisation is an important factor in determining the standard electrode potential of a metal, metals with very high enthalpy of atomisation (i.e., very high boiling point) tend to be noble in their reactions."},{"sec": "Physical properties","ids": [57],"t": "4d and 5d metals have higher ∆aH than 3d → far more metal–metal bonding in heavy transition metal compounds.","exc": false,"tab": false,"src": "d","page": 5,"o": "Another generalisation that may be drawn from Fig. 4.2 is that the metals of the second and third series have greater enthalpies of atomisation than the corresponding elements of the first series; this is an important factor in accounting for the occurrence of much more frequent metal – metal bonding in compounds of the heavy transition metals."},{"sec": "Physical properties","ids": [92],"t": "**Sc–Zn: Zn has the lowest ∆aH, 126 kJ mol^–1.**","exc": true,"tab": false,"src": "d","page": 7,"o": "In the series Sc (Z = 21) to Zn (Z = 30), the enthalpy of atomisation of zinc is the lowest, i.e., 126 kJ mol^–1."},{"sec": "Physical properties","ids": [95],"t": "Exchange energy stabilises the energy state.","exc": false,"tab": false,"src": "d","page": 8,"o": "Exchange energy is responsible for the stabilisation of energy state."},{"sec": "Physical properties","ids": [430],"t": "Zn: no 3d electrons in metallic bonding; all other 3d metals use d electrons.","exc": false,"tab": false,"src": "d","page": 29,"o": "In the formation of metallic bonds, no eletrons from 3d-orbitals are involved in case of zinc, while in all other metals of the 3d series, electrons from the d-orbitals are always involved in the formation of metallic bonds."},{"sec": "Atomic and ionic sizes","ids": [58],"t": "Same-charge ions in a series: radius decreases steadily with Z.","exc": false,"tab": false,"src": "d","page": 5,"o": "In general, ions of the same charge in a given series show progressive decrease in radius with increasing atomic number."},{"sec": "Atomic and ionic sizes","ids": [59,60],"t": "Reason: new electron enters d; d shielding is poor, so attraction on the outermost electron rises and radius falls.","exc": false,"tab": false,"src": "d","page": 5,"o": "This is because the new electron enters a d orbital each time the nuclear charge increases by unity. It may be recalled that the shielding effect of a d electron is not that effective, hence the net electrostatic attraction between the nuclear charge and the outermost electron increases and the ionic radius decreases."},{"sec": "Atomic and ionic sizes","ids": [61],"t": "Atomic radii show the same trend.","exc": false,"tab": false,"src": "d","page": 5,"o": "The same trend is observed in the atomic radii of a given series."},{"sec": "Atomic and ionic sizes","ids": [62],"t": "Variation within a series is small.","exc": false,"tab": false,"src": "d","page": 5,"o": "However, the variation within a series is quite small."},{"sec": "Atomic and ionic sizes","ids": [64],"t": "**3d → 4d radii increase, but 5d ≈ 4d.**","exc": true,"tab": false,"src": "d","page": 5,"o": "The curves in Fig. 4.3 show an increase from the first (3d) to the second (4d) series of the elements but the radii of the third (5d) series are virtually the same as those of the corresponding members of the second series."},{"sec": "Atomic and ionic sizes","ids": [65,66,67],"t": "Cause: 4f fills before 5d; this regular decrease (lanthanoid contraction) cancels the expected size increase.","exc": false,"tab": false,"src": "d","page": 5,"o": "This phenomenon is associated with the intervention of the 4f orbitals which must be filled before the 5d series of elements begin. The filling of 4f before 5d orbital results in a regular decrease in atomic radii called Lanthanoid contraction which essentially compensates for the expected increase in atomic size with increasing atomic number."},{"sec": "Atomic and ionic sizes","ids": [68],"t": "**Result: 4d and 5d have similar radii (Zr 160 pm, Hf 159 pm) and very similar properties.**","exc": true,"tab": false,"src": "d","page": 6,"o": "The net result of the lanthanoid contraction is that the second and the third d series exhibit similar radii (e.g., Zr 160 pm, Hf 159 pm) and have very similar physical and chemical properties much more than that expected on the basis of usual family relationship."},{"sec": "Atomic and ionic sizes","ids": [69],"t": "Lanthanoid contraction has the same cause as in a transition series: imperfect shielding within the same set of orbitals.","exc": false,"tab": false,"src": "d","page": 6,"o": "The factor responsible for the lanthanoid contraction is somewhat similar to that observed in an ordinary transition series and is attributed to similar cause, i.e., the imperfect shielding of one electron by another in the same set of orbitals."},{"sec": "Atomic and ionic sizes","ids": [70],"t": "4f–4f shielding is worse than d–d shielding, so the whole 4f^n shell shrinks fairly regularly as Z rises.","exc": false,"tab": false,"src": "d","page": 6,"o": "However, the shielding of one 4f electron by another is less than that of one d electron by another, and as the nuclear charge increases along the series, there is fairly regular decrease in the size of the entire 4f^n orbitals."},{"sec": "Atomic and ionic sizes","ids": [71,72],"t": "Smaller radius + larger mass → density increases (marked from Ti to Cu).","exc": false,"tab": false,"src": "d","page": 6,"o": "The decrease in metallic radius coupled with increase in atomic mass results in a general increase in the density of these elements. Thus, from titanium (Z = 22) to copper (Z = 29) the significant increase in the density may be noted."},{"sec": "Atomic and ionic sizes","ids": [75],"t": "Many unpaired electrons → stronger interatomic bonding → higher ∆aH.","exc": false,"tab": false,"src": "d","page": 7,"o": "Because of large number of unpaired electrons in their atoms they have stronger interatomic interaction and hence stronger bonding between atoms resulting in higher enthalpies of atomisation."},{"sec": "Ionisation enthalpies","ids": [76],"t": "IE increases left → right in each series (nuclear charge rises as inner d fills).","exc": false,"tab": false,"src": "d","page": 7,"o": "There is an increase in ionisation enthalpy along each series of the transition elements from left to right due to an increase in nuclear charge which accompanies the filling of the inner d orbitals."},{"sec": "Ionisation enthalpies","ids": [78],"t": "Successive IEs rise less steeply than for non-transition elements.","exc": false,"tab": false,"src": "d","page": 7,"o": "These values show that the successive enthalpies of these elements do not increase as steeply as in the case of non-transition elements."},{"sec": "Ionisation enthalpies","ids": [79],"t": "IE variation across a transition series is much smaller than across a period of non-transition elements.","exc": false,"tab": false,"src": "d","page": 7,"o": "The variation in ionisation enthalpy along a series of transition elements is much less in comparison to the variation along a period of non-transition elements."},{"sec": "Ionisation enthalpies","ids": [80],"t": "IE1 generally increases; increases in IE2 and IE3 along a series are much larger.","exc": false,"tab": false,"src": "d","page": 7,"o": "The first ionisation enthalpy, in general, increases, but the magnitude of the increase in the second and third ionisation enthalpies for the successive elements, is much higher along a series."},{"sec": "Ionisation enthalpies","ids": [81],"t": "Irregular IE1 in 3d series: removing one electron changes the relative energies of 4s and 3d.","exc": false,"tab": false,"src": "d","page": 7,"o": "The irregular trend in the first ionisation enthalpy of the metals of 3d series, though of little chemical significance, can be accounted for by considering that the removal of one electron alters the relative energies of 4s and 3d orbitals."},{"sec": "Ionisation enthalpies","ids": [82],"t": "On ionisation, ns electrons leave before (n–1)d.","exc": false,"tab": false,"src": "d","page": 7,"o": "You have learnt that when d-block elements form ions, ns electrons are lost before (n – 1) d electrons."},{"sec": "Ionisation enthalpies","ids": [83],"t": "Sc → Zn: nuclear charge rises but electrons go into the inner 3d.","exc": false,"tab": false,"src": "d","page": 7,"o": "As we move along the period in 3d series, we see that nuclear charge increases from scandium to zinc but electrons are added to the orbital of inner subshell, i.e., 3d orbitals."},{"sec": "Ionisation enthalpies","ids": [84,85,86],"t": "3d electrons shield 4s better than outer electrons shield each other → radii fall slowly → IE rises only slightly along 3d.","exc": false,"tab": false,"src": "d","page": 7,"o": "These 3d electrons shield the 4s electrons from the increasing nuclear charge somewhat more effectively than the outer shell electrons can shield one another. Therefore, the atomic radii decrease less rapidly. Thus, ionization energies increase only slightly along the 3d series."},{"sec": "Ionisation enthalpies","ids": [87,88],"t": "M^2+ and higher: d^n, no 4s; IE2 should rise steadily (d electrons don't shield each other well, different directions).","exc": false,"tab": false,"src": "d","page": 7,"o": "The doubly or more highly charged ions have d n configurations with no 4s electrons. A general trend of increasing values of second ionisation enthalpy is expected as the effective nuclear charge increases because one d electron does not shield another electron from the influence of nuclear charge because d-orbitals differ in direction."},{"sec": "Ionisation enthalpies","ids": [89,90],"t": "**Steady rise breaks at Mn^2+ (IE2) and Fe^3+ (IE3): both give d^5.**","exc": true,"tab": false,"src": "d","page": 7,"o": "However, the trend of steady increase in second and third ionisation enthalpy breaks for the formation of Mn^2+ and Fe^3+ respectively. In both the cases, ions have d^5 configuration."},{"sec": "Ionisation enthalpies","ids": [96],"t": "Exchange energy ∝ number of parallel-spin pairs in degenerate orbitals.","exc": false,"tab": false,"src": "d","page": 8,"o": "Exchange energy is approximately proportional to the total number of possible pairs of parallel spins in the degenerate orbitals."},{"sec": "Ionisation enthalpies","ids": [97,98,99],"t": "Max single occupation with parallel spins (Hund) is lowest energy; more stability → harder to ionise.","exc": false,"tab": false,"src": "d","page": 8,"o": "When several electrons occupy a set of degenerate orbitals, the lowest energy state corresponds to the maximum possible extent of single occupation of orbital and parallel spins (Hunds rule). The loss of exchange energy increases the stability. As the stability increases, the ionisation becomes more difficult."},{"sec": "Ionisation enthalpies","ids": [100],"t": "No exchange energy is lost at d^6.","exc": false,"tab": false,"src": "d","page": 8,"o": "There is no loss of exchange energy at d6 configuration."},{"sec": "Ionisation enthalpies","ids": [101],"t": "**Mn^+ (3d^5 4s^1) has lower IE than Cr^+ (d^5).**","exc": true,"tab": false,"src": "d","page": 8,"o": "Mn^+ has 3d^5 4s^1 configuration and configuration of Cr^+ is d^5, therefore, ionisation enthalpy of Mn^+ is lower than Cr^+."},{"sec": "Ionisation enthalpies","ids": [102,103,104],"t": "**Fe^2+ (d^6) ionises more easily than Mn^2+ (d^5): IE3 of Fe < IE3 of Mn.**","exc": true,"tab": false,"src": "d","page": 8,"o": "In the same way, Fe^2+ has d^6 configuration and Mn^2+ has 3d^5 configuration. Hence, ionisation enthalpy of Fe^2+ is lower than the Mn^2+. In other words, we can say that the third ionisation enthalpy of Fe is lower than that of Mn."},{"sec": "Ionisation enthalpies","ids": [105],"t": "M^2+ from gaseous atom needs ∆aH + IE1 + IE2.","exc": false,"tab": false,"src": "d","page": 8,"o": "To form the M 2+ ions from the gaseous atoms, the sum of the first and second ionisation enthalpy is required in addition to the enthalpy of atomisation."},{"sec": "Ionisation enthalpies","ids": [106],"t": "**IE2 is unusually high for Cr and Cu** (M^+ is d^5 and d^10).","exc": true,"tab": false,"src": "d","page": 8,"o": "The dominant term is the second ionisation enthalpy which shows unusually high values for Cr and Cu where M^+ ions have the d^5 and d^10 configurations respectively."},{"sec": "Ionisation enthalpies","ids": [107],"t": "**IE2 of Zn is low**: removing a 4s electron gives stable d^10.","exc": true,"tab": false,"src": "d","page": 8,"o": "The value for Zn is correspondingly low as the ionisation causes the removal of one 4s electron which results in the formation of stable d^10 configuration."},{"sec": "Ionisation enthalpies","ids": [108],"t": "IE3 (no 4s factor): high for removal from d^5 (Mn^2+) and d^10 (Zn^2+).","exc": false,"tab": false,"src": "d","page": 8,"o": "The trend in the third ionisation enthalpies is not complicated by the 4s orbital factor and shows the greater difficulty of removing an electron from the d^5 (Mn^2+) and d^10 (Zn^2+) ions."},{"sec": "Ionisation enthalpies","ids": [109],"t": "IE3 values are generally quite high.","exc": false,"tab": false,"src": "d","page": 8,"o": "In general, the third ionisation enthalpies are quite high."},{"sec": "Ionisation enthalpies","ids": [110],"t": "High IE3 of Cu, Ni, Zn → oxidation states above +2 hard to get.","exc": false,"tab": false,"src": "d","page": 8,"o": "Also the high values for third ionisation enthalpies of copper, nickel and zinc indicate why it is difficult to obtain oxidation state greater than two for these elements."},{"sec": "Oxidation states","ids": [115,116],"t": "Most oxidation states in or near the middle; **Mn shows every state from +2 to +7.**","exc": false,"tab": false,"src": "d","page": 9,"o": "The elements which give the greatest number of oxidation states occur in or near the middle of the series. Manganese, for example, exhibits all the oxidation states from +2 to +7."},{"sec": "Oxidation states","ids": [117],"t": "Fewer states at the ends: too few electrons (Sc, Ti) or too many d electrons, fewer orbitals to share (Cu, Zn).","exc": false,"tab": false,"src": "d","page": 9,"o": "The lesser number of oxidation states at the extreme ends stems from either too few electrons to lose or share (Sc, Ti) or too many d electrons (hence fewer orbitals available in which to share electrons with others) for higher valence (Cu, Zn)."},{"sec": "Oxidation states","ids": [118,119],"t": "**Sc(II) virtually unknown; Ti(IV) more stable than Ti(III), Ti(II); Zn only +2.**","exc": true,"tab": false,"src": "d","page": 9,"o": "Thus, early in the series scandium(II) is virtually unknown and titanium (IV) is more stable than Ti(III) or Ti(II). At the other end, the only oxidation state of zinc is +2 (no d electrons are involved)."},{"sec": "Oxidation states","ids": [120],"t": "Max stable state = s + d electrons up to Mn (TiO2, VO2^+, CrO4^2–, MnO4^–), then abrupt fall: Fe(II,III), Co(II,III), Ni(II), Cu(I,II), Zn(II).","exc": false,"tab": false,"src": "d","page": 9,"o": "The maximum oxidation states of reasonable stability correspond in value to the sum of the s and d electrons upto manganese (TiO2, VO2^+, CrO4^2–, MnO4^–) followed by a rather abrupt decrease in stability of higher oxidation states, so that the typical species to follow are Fe(II,III), Co(II,III), Ni(II), Cu(I,II), Zn(II)."},{"sec": "Oxidation states","ids": [121,122],"t": "Transition element oxidation states differ by one, e.g. V(II), V(III), V(IV), V(V); non-transition ones normally differ by two.","exc": false,"tab": false,"src": "d","page": 9,"o": "The variability of oxidation states, a characteristic of transition elements, arises out of incomplete filling of d orbitals in such a way that their oxidation states differ from each other by unity, e.g., V(II), V(III), V(IV), V(V). This is in contrast with the variability of oxidation states of non transition elements where oxidation states normally differ by a unit of two."},{"sec": "Oxidation states","ids": [123],"t": "Group trend in oxidation states is notable across groups 4–10.","exc": false,"tab": false,"src": "d","page": 9,"o": "An interesting feature in the variability of oxidation states of the d– block elements is noticed among the groups (groups 4 through 10)."},{"sec": "Oxidation states","ids": [124,125],"t": "**Opposite of p-block: heavier d members favour higher states. Group 6: Mo(VI), W(VI) more stable than Cr(VI).**","exc": true,"tab": false,"src": "d","page": 9,"o": "Although in the p–block the lower oxidation states are favoured by the heavier members (due to inert pair effect), the opposite is true in the groups of d-block. For example, in group 6, Mo(VI) and W(VI) are found to be more stable than Cr(VI)."},{"sec": "Oxidation states","ids": [126],"t": "So acidic dichromate (Cr(VI)) is a strong oxidant; MoO3 and WO3 are not.","exc": false,"tab": false,"src": "d","page": 9,"o": "Thus Cr(VI) in the form of dichromate in acidic medium is a strong oxidising agent, whereas MoO3 and WO3 are not."},{"sec": "Oxidation states","ids": [127,128],"t": "Low oxidation states with π-acceptor ligands: Ni(CO)4 and Fe(CO)5 have the metal at 0.","exc": false,"tab": false,"src": "d","page": 9,"o": "Low oxidation states are found when a complex compound has ligands capable of π-acceptor character in addition to the σ-bonding. For example, in Ni(CO)4 and Fe(CO)5, the oxidation state of nickel and iron is zero."},{"sec": "Oxidation states","ids": [130],"t": "**Sc (Z = 21) has no variable oxidation states.**","exc": true,"tab": false,"src": "d","page": 9,"o": "Scandium (Z = 21) does not exhibit variable oxidation states."},{"sec": "M²⁺/M standard electrode potentials","ids": [133,134],"t": "**Cu: positive E°, can't liberate H2 from acids**; only oxidising acids (HNO3, hot conc. H2SO4) react, and get reduced.","exc": true,"tab": false,"src": "d","page": 10,"o": "The unique behaviour of Cu, having a positive E°, accounts for its inability to liberate H2 from acids. Only oxidising acids (nitric and hot concentrated sulphuric) react with Cu, the acids being reduced."},{"sec": "M²⁺/M standard electrode potentials","ids": [135],"t": "Cu(s) → Cu^2+(aq) energy cost is not balanced by hydration enthalpy.","exc": false,"tab": false,"src": "d","page": 10,"o": "The high energy to transform Cu(s) to Cu^2+(aq) is not balanced by its hydration enthalpy."},{"sec": "M²⁺/M standard electrode potentials","ids": [136,141],"t": "E° becomes less negative across the series as IE1 + IE2 rises.","exc": false,"tab": false,"src": "d","page": 10,"o": "The general trend towards less negative E° values across the series is related to the general increase in the sum of the first and second ionisation enthalpies."},{"sec": "M²⁺/M standard electrode potentials","ids": [138,139],"t": "**Cr^2+ is reducing: d^4 → d^3 (half-filled t2g).**","exc": true,"tab": false,"src": "d","page": 10,"o": "Cr^2+ is reducing as its configuration changes from d^4 to d^3, the latter having a half-filled t2g level."},{"sec": "M²⁺/M standard electrode potentials","ids": [140],"t": "**Mn^3+ → Mn^2+ gives extra-stable d^5** (so Mn^3+ is oxidising).","exc": true,"tab": false,"src": "d","page": 10,"o": "On the other hand, the change from Mn^3+ to Mn^2+ results in the half-filled (d^5) configuration which has extra stability."},{"sec": "M²⁺/M standard electrode potentials","ids": [142],"t": "**E° for Mn, Ni, Zn more negative than the trend predicts.**","exc": true,"tab": false,"src": "d","page": 10,"o": "It is interesting to note that the value of E° for Mn, Ni and Zn are more negative than expected from the trend."},{"sec": "M²⁺/M standard electrode potentials","ids": [172],"t": "Mn^2+ (d^5) and Zn (d^10): stable subshells explain E°; **Ni: highest negative hydration enthalpy.**","exc": true,"tab": false,"src": "d","page": 13,"o": "Whereas the stabilities of half-filled d subshell (d^5) in Mn^2+ and completely filled d subshell (d^10) in zinc are related to their E° values; for nickel, E° value is related to the highest negative enthalpy of hydration."},{"sec": "M²⁺/M standard electrode potentials","ids": [430],"t": "**Cr^2+ is a stronger reductant than Fe^2+.**","exc": true,"tab": false,"src": "d","page": 29,"o": "Cr^2+ is stronger reducing agent than Fe^2+."},{"sec": "M³⁺/M²⁺ standard electrode potentials","ids": [145],"t": "Low E°(M^3+/M^2+) for Sc: Sc^3+ has noble gas configuration.","exc": false,"tab": false,"src": "d","page": 11,"o": "The low value for Sc reflects the stability of Sc^3+ which has a noble gas configuration."},{"sec": "M³⁺/M²⁺ standard electrode potentials","ids": [146],"t": "Highest for Zn: electron would leave stable d^10 of Zn^2+.","exc": false,"tab": false,"src": "d","page": 11,"o": "The highest value for Zn is due to the removal of an electron from the stable d^10 configuration of Zn^2+."},{"sec": "M³⁺/M²⁺ standard electrode potentials","ids": [147],"t": "**High for Mn (Mn^2+ d^5 stable); low for Fe (Fe^3+ d^5 stable).**","exc": true,"tab": false,"src": "d","page": 11,"o": "The comparatively high value for Mn shows that Mn^2+ (d^5) is particularly stable, whereas comparatively low value for Fe shows the extra stability of Fe^3+ (d^5)."},{"sec": "M³⁺/M²⁺ standard electrode potentials","ids": [148],"t": "Low for V: V^2+ has half-filled t2g.","exc": false,"tab": false,"src": "d","page": 11,"o": "The comparatively low value for V is related to the stability of V^2+ (half-filled t2g level)."},{"sec": "M³⁺/M²⁺ standard electrode potentials","ids": [164,165],"t": "**Large IE3 of Mn (d^5 → d^4) is why Mn(+3) matters little.**","exc": true,"tab": false,"src": "d","page": 13,"o": "Much larger third ionisation energy of Mn (where the required change is d^5 to d^4) is mainly responsible for this. This also explains why the +3 state of Mn is of little importance."},{"sec": "Stability of higher oxidation states","ids": [150],"t": "Highest states in halides: TiX4, VF5, CrF6.","exc": false,"tab": false,"src": "d","page": 11,"o": "The highest oxidation numbers are achieved in TiX4 (tetrahalides), VF5 and CrF6."},{"sec": "Stability of higher oxidation states","ids": [150],"t": "**Mn(+7) has no simple halide, but MnO3F exists. Beyond Mn, only FeX3 and CoF3 are trihalides.**","exc": false,"tab": false,"src": "d","page": 11,"o": "The +7 state for Mn is not represented in simple halides but MnO3F is known, and beyond Mn no metal has a trihalide except FeX3 and CoF3."},{"sec": "Stability of higher oxidation states","ids": [150],"t": "F stabilises highest states via higher lattice energy (CoF3) or higher bond enthalpy in covalent compounds (VF5, CrF6).","exc": false,"tab": false,"src": "d","page": 11,"o": "The ability of fluorine to stabilise the highest oxidation state is due to either higher lattice energy as in the case of CoF3, or higher bond enthalpy terms for the higher covalent compounds, e.g., VF5 and CrF6."},{"sec": "Stability of higher oxidation states","ids": [150],"t": "V(+5) only as VF5; other halides hydrolyse to oxohalides VOX3.","exc": false,"tab": false,"src": "d","page": 11,"o": "Although V(+5) is represented only by VF5, the other halides, however, undergo hydrolysis to give oxohalides, VOX3."},{"sec": "Stability of higher oxidation states","ids": [150,151],"t": "**Low-state fluorides unstable (VX2, X = Cl, Br, I; also CuX). All Cu(II) halides known except the iodide.**","exc": true,"tab": false,"src": "d","page": 11,"o": "Another feature of fluorides is their instability in the low oxidation states e.g., VX2 (X = CI, Br or I) and the same applies to CuX. On the other hand, all Cu(II) halides are known except the iodide."},{"sec": "Stability of higher oxidation states","ids": [152],"t": "**Cu^2+ oxidises I^– to I2:** 2Cu^2+ + 4I^– → Cu2I2(s) + I2","exc": true,"tab": false,"src": "d","page": 12,"o": "In this case, Cu^2+ oxidises I^– to I2: 2Cu^2+ + 4I^– → Cu2I2(s) + I2"},{"sec": "Stability of higher oxidation states","ids": [152],"t": "**Many Cu(I) compounds disproportionate in water:** 2Cu^+ → Cu^2+ + Cu","exc": true,"tab": false,"src": "d","page": 12,"o": "However, many copper (I) compounds are unstable in aqueous solution and undergo disproportionation. 2Cu^+ → Cu^2+ + Cu"},{"sec": "Stability of higher oxidation states","ids": [152],"t": "**Cu^2+(aq) beats Cu^+(aq):** much more negative ∆hydH° of Cu^2+ outweighs IE2 of Cu.","exc": true,"tab": false,"src": "d","page": 12,"o": "The stability of Cu^2+(aq) rather than Cu^+(aq) is due to the much more negative Δ_hydH° of Cu^2+(aq) than Cu^+, which more than compensates for the second ionisation enthalpy of Cu."},{"sec": "Stability of higher oxidation states","ids": [153],"t": "Highest oxide oxidation number = group number, from Sc2O3 to Mn2O7.","exc": false,"tab": false,"src": "d","page": 12,"o": "The highest oxidation number in the oxides coincides with the group number and is attained in Sc2O3 to Mn2O7."},{"sec": "Stability of higher oxidation states","ids": [153],"t": "**Nothing above Fe2O3 for Fe**; ferrates(VI) (FeO4)^2– form in alkali but decompose to Fe2O3 + O2.","exc": true,"tab": false,"src": "d","page": 12,"o": "Beyond Group 7, no higher oxides of Fe above Fe2O3, are known, although ferrates (VI)(FeO4)^2–, are formed in alkaline media but they readily decompose to Fe2O3 and O2."},{"sec": "Stability of higher oxidation states","ids": [153],"t": "Oxocations stabilise V(V) as VO2^+, V(IV) as VO^2+, Ti(IV) as TiO^2+.","exc": false,"tab": false,"src": "d","page": 12,"o": "Besides the oxides, oxocations stabilise V(V) as VO2^+, V(IV) as VO^2+ and Ti(IV) as TiO^2+."},{"sec": "Stability of higher oxidation states","ids": [154,155],"t": "**O beats F at stabilising high states: highest Mn fluoride MnF4, highest oxide Mn2O7.** O forms multiple bonds to metals.","exc": true,"tab": false,"src": "d","page": 12,"o": "The ability of oxygen to stabilise these high oxidation states exceeds that of fluorine. Thus the highest Mn fluoride is MnF4 whereas the highest oxide is Mn2O7. The ability of oxygen to form multiple bonds to metals explains its superiority."},{"sec": "Stability of higher oxidation states","ids": [156],"t": "Mn2O7 (covalent): each Mn tetrahedral, with a Mn–O–Mn bridge.","exc": false,"tab": false,"src": "d","page": 12,"o": "In the covalent oxide Mn2O7, each Mn is tetrahedrally surrounded by O’s including a Mn–O–Mn bridge."},{"sec": "Stability of higher oxidation states","ids": [157],"t": "Tetrahedral [MO4]^n– known for V(V), Cr(VI), Mn(V), Mn(VI), Mn(VII).","exc": false,"tab": false,"src": "d","page": 12,"o": "The tetrahedral [MO4]^n– ions are known for V(V), Cr(VI), Mn(V), Mn(VI) and Mn(VII)."},{"sec": "Stability of higher oxidation states","ids": [158,159],"t": "Oxidising power VO2^+ < Cr2O7^2– < MnO4^–: increasing stability of the reduced species.","exc": false,"tab": false,"src": "d","page": 12,"o": "How would you account for the increasing oxidising power in the series VO2^+ < Cr2O7^2– < MnO4^–? This is due to the increasing stability of the lower species to which they are reduced."},{"sec": "Stability of higher oxidation states","ids": [161],"t": "E°(M^2+/M) irregular: irregular IE1 + IE2, and sublimation enthalpies much lower for Mn and V.","exc": false,"tab": false,"src": "d","page": 13,"o": "The Eo (M 2+ /M) values are not regular which can be explained from the irregular variation of ionisation enthalpies ( i i    1 2 H H ) and also the sublimation enthalpies which are relatively much less for manganese and vanadium."},{"sec": "Stability of higher oxidation states","ids": [430],"t": "Small size + high EN let O and F oxidise metals to their highest state.","exc": false,"tab": false,"src": "d","page": 29,"o": "Because of small size and high electronegativity oxygen or fluorine can oxidise the metal to its highest oxidation state."},{"sec": "Chemical reactivity and E° values","ids": [166],"t": "Many dissolve in mineral acids; a few are 'noble', unaffected by single acids.","exc": false,"tab": false,"src": "d","page": 13,"o": "Many of them are sufficiently electropositive to dissolve in mineral acids, although a few are ‘noble’—that is, they are unaffected by single acids."},{"sec": "Chemical reactivity and E° values","ids": [167],"t": "3d metals except Cu are fairly reactive, oxidised by 1 M H^+, though sometimes slowly.","exc": false,"tab": false,"src": "d","page": 13,"o": "The metals of the first series with the exception of copper are relatively more reactive and are oxidised by 1M H^+, though the actual rate at which these metals react with oxidising agents like hydrogen ion (H^+) is sometimes slow."},{"sec": "Chemical reactivity and E° values","ids": [168],"t": "**Ti and V are passive to dilute non-oxidising acids at room temperature.**","exc": true,"tab": false,"src": "d","page": 13,"o": "For example, titanium and vanadium, in practice, are passive to dilute non oxidising acids at room temperature."},{"sec": "Chemical reactivity and E° values","ids": [169],"t": "E°(M^2+/M): tendency to form M^2+ decreases across the series.","exc": false,"tab": false,"src": "d","page": 13,"o": "The E° values for M^2+/M indicate a decreasing tendency to form divalent cations across the series."},{"sec": "Chemical reactivity and E° values","ids": [173],"t": "**Mn^3+ and Co^3+ are the strongest oxidising agents in water** (M^3+/M^2+).","exc": false,"tab": false,"src": "d","page": 13,"o": "An examination of the E° values for the redox couple M^3+/M^2+ shows that Mn^3+ and Co^3+ ions are the strongest oxidising agents in aqueous solutions."},{"sec": "Chemical reactivity and E° values","ids": [174],"t": "**Ti^2+, V^2+, Cr^2+ are strong reductants, liberate H2 from dilute acid:** 2Cr^2+(aq) + 2H^+(aq) → 2Cr^3+(aq) + H2(g)","exc": false,"tab": false,"src": "d","page": 13,"o": "The ions Ti^2+, V^2+ and Cr^2+ are strong reducing agents and will liberate hydrogen from a dilute acid, e.g., 2Cr^2+(aq) + 2H^+(aq) → 2Cr^3+(aq) + H2(g)"},{"sec": "Chemical reactivity and E° values","ids": [386],"t": "React with O, N, S and halogens to form binary compounds.","exc": false,"tab": false,"src": "d","page": 26,"o": "The transition metals react with a number of non-metals like oxygen, nitrogen, sulphur and halogens to form binary compounds."},{"sec": "Magnetic properties","ids": [175],"t": "Two main behaviours in a field: diamagnetism and paramagnetism.","exc": false,"tab": false,"src": "d","page": 13,"o": "When a magnetic field is applied to substances, mainly two types of magnetic behaviour are observed: diamagnetism and paramagnetism."},{"sec": "Magnetic properties","ids": [176],"t": "Diamagnetic: repelled. Paramagnetic: attracted.","exc": false,"tab": false,"src": "d","page": 13,"o": "Diamagnetic substances are repelled by the applied field while the paramagnetic substances are attracted."},{"sec": "Magnetic properties","ids": [177,178,179],"t": "Ferromagnetic: very strongly attracted, an extreme form of paramagnetism.","exc": false,"tab": false,"src": "d","page": 13,"o": "Substances which are attracted very strongly are said to be ferromagnetic. In fact, ferromagnetism is an extreme form of paramagnetism."},{"sec": "Magnetic properties","ids": [180],"t": "Many transition metal ions are paramagnetic.","exc": false,"tab": false,"src": "d","page": 14,"o": "Many of the transition metal ions are paramagnetic."},{"sec": "Magnetic properties","ids": [181],"t": "Paramagnetism comes from unpaired electrons (spin + orbital angular momentum).","exc": false,"tab": false,"src": "d","page": 14,"o": "Paramagnetism arises from the presence of unpaired electrons, each such electron having a magnetic moment associated with its spin angular momentum and orbital angular momentum."},{"sec": "Magnetic properties","ids": [182],"t": "First-series compounds: orbital contribution effectively quenched.","exc": false,"tab": false,"src": "d","page": 14,"o": "For the compounds of the first series of transition metals, the contribution of the orbital angular momentum is effectively quenched and hence is of no significance."},{"sec": "Magnetic properties","ids": [183],"t": "**Spin-only: μ = √(n(n+2)) BM**, n = unpaired electrons.","exc": false,"tab": false,"src": "d","page": 14,"o": "For these, the magnetic moment is determined by the number of unpaired electrons and is calculated by using the ‘spin-only’ formula, i.e., μ = √(n(n+2)) where n is the number of unpaired electrons and µ is the magnetic moment in units of Bohr magneton (BM)."},{"sec": "Magnetic properties","ids": [184],"t": "One unpaired electron: 1.73 BM.","exc": false,"tab": false,"src": "d","page": 14,"o": "A single unpaired electron has a magnetic moment of 1.73 Bohr magnetons (BM)."},{"sec": "Magnetic properties","ids": [185,186],"t": "μ rises with unpaired electrons, so measured μ tells you n.","exc": false,"tab": false,"src": "d","page": 14,"o": "The magnetic moment increases with the increasing number of unpaired electrons. Thus, the observed magnetic moment gives a useful indication about the number of unpaired electrons present in the atom, molecule or ion."},{"sec": "Magnetic properties","ids": [189],"t": "Table 4.7, calculated spin-only moments (BM): Ti^3+ 3d^1 1.73, V^2+ 3d^3 3.87, Cr^2+ 3d^4 4.90, Mn^2+ 3d^5 5.92, Fe^2+ 3d^6 4.90, Co^2+ 3d^7 3.87, Ni^2+ 3d^8 2.84, Cu^2+ 3d^9 1.73 BM.","exc": false,"tab": true,"src": "d","page": 14,"o": "Table 4.7, calculated spin-only moments (BM): Ti^3+ 3d^1 1.73, V^2+ 3d^3 3.87, Cr^2+ 3d^4 4.90, Mn^2+ 3d^5 5.92, Fe^2+ 3d^6 4.90, Co^2+ 3d^7 3.87, Ni^2+ 3d^8 2.84, Cu^2+ 3d^9 1.73 BM."},{"sec": "Magnetic properties","ids": [190,191],"t": "Z = 25: M^2+(aq) is d^5, five unpaired, μ = √35 = 5.92 BM.","exc": false,"tab": true,"src": "d","page": 14,"o": "For Z = 25, the divalent ion in aqueous solution has d^5 configuration (five unpaired electrons); µ = √(5(5+2)) = 5.92 BM."},{"sec": "Magnetic properties","ids": [435],"t": "Experimental moments: K4[Mn(CN)6] 2.2 BM, [Fe(H2O)6]^2+ 5.3 BM, K2[MnCl4] 5.9 BM.","exc": false,"tab": true,"src": "d","page": 29,"o": "Experimental magnetic moments: K4[Mn(CN)6] 2.2 BM, [Fe(H2O)6]^2+ 5.3 BM, K2[MnCl4] 5.9 BM."},{"sec": "Coloured ions","ids": [192],"t": "Table 4.8, colours of aquated ions: Sc^3+ colourless, Ti^4+ colourless, Ti^3+ purple, V^4+ blue, V^3+ green, V^2+ violet, Cr^3+ violet, Mn^3+ violet, Cr^2+ blue, Mn^2+ pink, Fe^3+ yellow, Fe^2+ green, Co^3+ blue, Co^2+ pink, Ni^2+ green, Cu^2+ blue, Zn^2+ colourless.","exc": false,"tab": true,"src": "d","page": 15,"o": "Table 4.8, colours of aquated ions: Sc^3+ colourless, Ti^4+ colourless, Ti^3+ purple, V^4+ blue, V^3+ green, V^2+ violet, Cr^3+ violet, Mn^3+ violet, Cr^2+ blue, Mn^2+ pink, Fe^3+ yellow, Fe^2+ green, Co^3+ blue, Co^2+ pink, Ni^2+ green, Cu^2+ blue, Zn^2+ colourless."},{"sec": "Coloured ions","ids": [193,194],"t": "Colour: d–d excitation; absorbed frequency usually visible.","exc": false,"tab": false,"src": "d","page": 15,"o": "When an electron from a lower energy d orbital is excited to a higher energy d orbital, the energy of excitation corresponds to the frequency of light absorbed. This frequency generally lies in the visible region."},{"sec": "Coloured ions","ids": [195,196],"t": "Observed colour = complement of absorbed light; absorbed frequency depends on the ligand.","exc": false,"tab": false,"src": "d","page": 15,"o": "The colour observed corresponds to the complementary colour of the light absorbed. The frequency of the light absorbed is determined by the nature of the ligand."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [200,201],"t": "Complexes: metal ion binds anions or neutral molecules, e.g. [Fe(CN)6]^3–, [Fe(CN)6]^4–, [Cu(NH3)4]^2+, [PtCl4]^2–.","exc": false,"tab": false,"src": "d","page": 15,"o": "Complex compounds are those in which the metal ions bind a number of anions or neutral molecules giving complex species with characteristic properties. A few examples are: [Fe(CN)6]^3–, [Fe(CN)6]^4–, [Cu(NH3)4]^2+ and [PtCl4]^2–."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [204,205],"t": "Many complexes: small ions, high charge, d orbitals available for bonding.","exc": false,"tab": false,"src": "d","page": 16,"o": "The transition metals form a large number of complex compounds. This is due to the comparatively smaller sizes of the metal ions, their high ionic charges and the availability of d orbitals for bond formation."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [206,207],"t": "Catalysis: multiple oxidation states + complex formation.","exc": false,"tab": false,"src": "d","page": 16,"o": "The transition metals and their compounds are known for their catalytic activity. This activity is ascribed to their ability to adopt multiple oxidation states and to form complexes."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [208],"t": "V2O5 (Contact process), finely divided Fe (Haber), Ni (catalytic hydrogenation).","exc": false,"tab": false,"src": "d","page": 16,"o": "Vanadium(V) oxide (in Contact Process), finely divided iron (in Haber’s Process), and nickel (in Catalytic Hydrogenation) are some of the examples."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [209],"t": "Surface catalysis: bonds form between reactants and surface atoms (3d metals use 3d and 4s electrons).","exc": false,"tab": false,"src": "d","page": 16,"o": "Catalysts at a solid surface involve the formation of bonds between reactant molecules and atoms of the surface of the catalyst (first row transition metals utilise 3d and 4s electrons for bonding)."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [210],"t": "Raises reactant concentration at the surface and weakens their bonds (lower activation energy).","exc": false,"tab": false,"src": "d","page": 16,"o": "This has the effect of increasing the concentration of the reactants at the catalyst surface and also weakening of the bonds in the reacting molecules (the activation energy is lowering)."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [211],"t": "Changing oxidation state makes ions better catalysts.","exc": false,"tab": false,"src": "d","page": 16,"o": "Also because the transition metal ions can change their oxidation states, they become more effective as catalysts."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [212],"t": "**Fe(III) catalyses I^– + persulphate:** 2I^– + S2O8^2– → I2 + 2SO4^2–","exc": false,"tab": false,"src": "d","page": 16,"o": "For example, iron(III) catalyses the reaction between iodide and persulphate ions. 2I^– + S2O8^2– → I2 + 2SO4^2–"},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [212],"t": "Mechanism: 2Fe^3+ + 2I^– → 2Fe^2+ + I2; 2Fe^2+ + S2O8^2– → 2Fe^3+ + 2SO4^2–","exc": false,"tab": false,"src": "d","page": 16,"o": "An explanation of this catalytic action can be given as: 2Fe^3+ + 2I^– → 2Fe^2+ + I2; 2Fe^2+ + S2O8^2– → 2Fe^3+ + 2SO4^2–"},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [212,213],"t": "Interstitial compounds: small H, C, N trapped in metal lattices; non-stoichiometric, neither ionic nor covalent: TiC, Mn4N, Fe3H, VH0.56, TiH1.7.","exc": false,"tab": false,"src": "d","page": 16,"o": "Interstitial compounds are those which are formed when small atoms like H, C or N are trapped inside the crystal lattices of metals. They are usually non stoichiometric and are neither typically ionic nor covalent, for example, TiC, Mn4N, Fe3H, VH0.56 and TiH1.7, etc."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [214,215,216,217],"t": "Interstitials: m.p. higher than pure metal; very hard (some borides near diamond); metallic conductivity; chemically inert.","exc": false,"tab": false,"src": "d","page": 16,"o": "The principal physical and chemical characteristics of these compounds are as follows: (i) They have high melting points, higher than those of pure metals. (ii) They are very hard, some borides approach diamond in hardness. (iii) They retain metallic conductivity. (iv) They are chemically inert."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [218],"t": "Alloy: blend of metals made by mixing.","exc": false,"tab": false,"src": "d","page": 16,"o": "An alloy is a blend of metals prepared by mixing the components."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [219,220],"t": "Homogeneous solid-solution alloys need metallic radii within ~15%.","exc": false,"tab": false,"src": "d","page": 16,"o": "Alloys may be homogeneous solid solutions in which the atoms of one metal are distributed randomly among the atoms of the other. Such alloys are formed by atoms with metallic radii that are within about 15 percent of each other."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [221],"t": "Similar radii → transition metals readily form alloys.","exc": false,"tab": false,"src": "d","page": 16,"o": "Because of similar radii and other characteristics of transition metals, alloys are readily formed by these metals."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [222],"t": "These alloys are hard, often high-melting.","exc": false,"tab": false,"src": "d","page": 16,"o": "The alloys so formed are hard and have often high melting points."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [223],"t": "Ferrous alloys: Cr, V, W, Mo, Mn used for steels and stainless steel.","exc": false,"tab": false,"src": "d","page": 16,"o": "The best known are ferrous alloys: chromium, vanadium, tungsten, molybdenum and manganese are used for the production of a variety of steels and stainless steel."},{"sec": "Complexes, catalysis, interstitials, alloys","ids": [224],"t": "With non-transition metals: brass (Cu–Zn), bronze (Cu–Sn).","exc": false,"tab": false,"src": "d","page": 16,"o": "Alloys of transition metals with non transition metals such as brass (copper-zinc) and bronze (copper-tin), are also of considerable industrial importance."},{"sec": "Oxides and oxoanions","ids": [227],"t": "Disproportionation: a state becomes unstable relative to one lower and one higher.","exc": false,"tab": false,"src": "d","page": 17,"o": "When a particular oxidation state becomes less stable relative to other oxidation states, one lower, one higher, it is said to undergo disproportionation."},{"sec": "Oxides and oxoanions","ids": [228],"t": "**Mn(VI) disproportionates in acid:** 3MnO4^2– + 4H^+ → 2MnO4^– + MnO2 + 2H2O","exc": false,"tab": false,"src": "d","page": 17,"o": "For example, manganese (VI) becomes unstable relative to manganese(VII) and manganese (IV) in acidic solution. 3MnO4^2– + 4H^+ → 2MnO4^– + MnO2 + 2H2O"},{"sec": "Oxides and oxoanions","ids": [229],"t": "**All except Sc form ionic MO oxides.**","exc": true,"tab": false,"src": "d","page": 17,"o": "All the metals except scandium form MO oxides which are ionic."},{"sec": "Oxides and oxoanions","ids": [232,233],"t": "**Higher oxidation number → less ionic. Mn2O7 is a covalent green oil.**","exc": true,"tab": false,"src": "d","page": 17,"o": "As the oxidation number of a metal increases, ionic character decreases. In the case of Mn, Mn2O7 is a covalent green oil."},{"sec": "Oxides and oxoanions","ids": [234,235],"t": "CrO3 and V2O5 have low m.p.; higher oxides are mainly acidic.","exc": false,"tab": false,"src": "d","page": 17,"o": "Even CrO3 and V2O5 have low melting points. In these higher oxides, the acidic character is predominant."},{"sec": "Oxides and oxoanions","ids": [236],"t": "Mn2O7 → HMnO4; CrO3 → H2CrO4 and H2Cr2O7.","exc": false,"tab": false,"src": "d","page": 17,"o": "Thus, Mn2O7 gives HMnO4 and CrO3 gives H2CrO4 and H2Cr2O7."},{"sec": "Oxides and oxoanions","ids": [237],"t": "**V2O5 is amphoteric (mainly acidic):** gives VO4^3– and VO2^+ salts.","exc": true,"tab": false,"src": "d","page": 17,"o": "V2O5 is, however, amphoteric though mainly acidic and it gives VO4^3– as well as VO2^+ salts."},{"sec": "Oxides and oxoanions","ids": [238],"t": "V: basic V2O3 → less basic V2O4 → amphoteric V2O5. V2O4 dissolves in acid as VO^2+ salts.","exc": false,"tab": false,"src": "d","page": 17,"o": "In vanadium there is gradual change from the basic V2O3 to less basic V2O4 and to amphoteric V2O5. V2O4 dissolves in acids to give VO^2+ salts."},{"sec": "Oxides and oxoanions","ids": [240],"t": "**CrO basic, Cr2O3 amphoteric.**","exc": false,"tab": false,"src": "d","page": 17,"o": "The well characterised CrO is basic but Cr2O3 is amphoteric."},{"sec": "Oxides and oxoanions","ids": [387,388],"t": "First-series oxides: metal + O2 at high temperature; dissolve in acids and bases to give oxometallic salts.","exc": false,"tab": false,"src": "d","page": 26,"o": "The first series transition metal oxides are generally formed from the reaction of metals with oxygen at high temperatures. These oxides dissolve in acids and bases to form oxometallic salts."},{"sec": "Potassium dichromate","ids": [241],"t": "K2Cr2O7: leather industry; oxidant for many azo compounds.","exc": false,"tab": false,"src": "d","page": 17,"o": "Potassium dichromate is a very important chemical used in leather industry and as an oxidant for preparation of many azo compounds."},{"sec": "Potassium dichromate","ids": [242],"t": "Dichromate from chromate; chromate from fusing chromite FeCr2O4 with Na2CO3 or K2CO3 in free air.","exc": false,"tab": false,"src": "d","page": 17,"o": "Dichromates are generally prepared from chromate, which in turn are obtained by the fusion of chromite ore (FeCr2O4) with sodium or potassium carbonate in free access of air."},{"sec": "Potassium dichromate","ids": [243],"t": "4FeCr2O4 + 8Na2CO3 + 7O2 → 8Na2CrO4 + 2Fe2O3 + 8CO2","exc": false,"tab": false,"src": "d","page": 17,"o": "The reaction with sodium carbonate occurs as follows: 4FeCr2O4 + 8Na2CO3 + 7O2 → 8Na2CrO4 + 2Fe2O3 + 8CO2"},{"sec": "Potassium dichromate","ids": [243],"t": "Yellow Na2CrO4 filtered, acidified with H2SO4 → orange Na2Cr2O7·2H2O: 2Na2CrO4 + 2H^+ → Na2Cr2O7 + 2Na^+ + H2O","exc": false,"tab": false,"src": "d","page": 17,"o": "The yellow solution of sodium chromate is filtered and acidified with sulphuric acid to give a solution from which orange sodium dichromate, Na2Cr2O7·2H2O can be crystallised. 2Na2CrO4 + 2H^+ → Na2Cr2O7 + 2Na^+ + H2O"},{"sec": "Potassium dichromate","ids": [244,245],"t": "Na2Cr2O7 is more soluble than K2Cr2O7, so add KCl to get the potassium salt.","exc": false,"tab": false,"src": "d","page": 18,"o": "Sodium dichromate is more soluble than potassium dichromate. The latter is therefore, prepared by treating the solution of sodium dichromate with potassium chloride."},{"sec": "Potassium dichromate","ids": [246],"t": "Na2Cr2O7 + 2KCl → K2Cr2O7 + 2NaCl (orange crystals).","exc": false,"tab": false,"src": "d","page": 18,"o": "Na2Cr2O7 + 2KCl → K2Cr2O7 + 2NaCl. Orange crystals of potassium dichromate crystallise out."},{"sec": "Potassium dichromate","ids": [247,248],"t": "Chromate ⇌ dichromate depending on pH; Cr is +6 in both.","exc": false,"tab": false,"src": "d","page": 18,"o": "The chromates and dichromates are interconvertible in aqueous solution depending upon pH of the solution. The oxidation state of chromium in chromate and dichromate is the same."},{"sec": "Potassium dichromate","ids": [248],"t": "2CrO4^2– + 2H^+ → Cr2O7^2– + H2O; Cr2O7^2– + 2OH^- → 2CrO4^2– + H2O","exc": false,"tab": false,"src": "d","page": 18,"o": "2CrO4^2– + 2H^+ → Cr2O7^2– + H2O; Cr2O7^2– + 2OH^- → 2CrO4^2– + H2O"},{"sec": "Potassium dichromate","ids": [249],"t": "**Chromate tetrahedral; dichromate = two tetrahedra sharing a corner, Cr–O–Cr 126°.**","exc": false,"tab": false,"src": "d","page": 18,"o": "The chromate ion is tetrahedral whereas the dichromate ion consists of two tetrahedra sharing one corner with Cr–O–Cr bond angle of 126°."},{"sec": "Potassium dichromate","ids": [250],"t": "Na and K dichromates: strong oxidants; Na salt more soluble, used in organic chemistry.","exc": false,"tab": false,"src": "d","page": 18,"o": "Sodium and potassium dichromates are strong oxidising agents; the sodium salt has a greater solubility in water and is extensively used as an oxidising agent in organic chemistry."},{"sec": "Potassium dichromate","ids": [251],"t": "**K2Cr2O7: primary standard in volumetric analysis.**","exc": false,"tab": false,"src": "d","page": 18,"o": "Potassium dichromate is used as a primary standard in volumetric analysis."},{"sec": "Potassium dichromate","ids": [252],"t": "Cr2O7^2– + 14H^+ + 6e^– → 2Cr^3+ + 7H2O (E° = 1.33 V)","exc": false,"tab": false,"src": "d","page": 18,"o": "In acidic solution, its oxidising action can be represented as follows: Cr2O7^2– + 14H^+ + 6e^– → 2Cr^3+ + 7H2O (E° = 1.33V)"},{"sec": "Potassium dichromate","ids": [252],"t": "Acidified K2Cr2O7 oxidises I^– → I2, S^2– → S, Sn(II) → Sn(IV), Fe(II) → Fe(III).","exc": false,"tab": false,"src": "d","page": 18,"o": "Thus, acidified potassium dichromate will oxidise iodides to iodine, sulphides to sulphur, tin(II) to tin(IV) and iron(II) salts to iron(III)."},{"sec": "Potassium dichromate","ids": [253],"t": "The half-reactions are noted below: 6I^– → 3I2 + 6e^–; 3Sn^2+ → 3Sn^4+ + 6e^–; 3H2S → 6H^+ + 3S + 6e^–; 6Fe^2+ → 6Fe^3+ + 6e^–","exc": false,"tab": false,"src": "d","page": 18,"o": "The half-reactions are noted below: 6I^– → 3I2 + 6e^–; 3Sn^2+ → 3Sn^4+ + 6e^–; 3H2S → 6H^+ + 3S + 6e^–; 6Fe^2+ → 6Fe^3+ + 6e^–"},{"sec": "Potassium dichromate","ids": [253],"t": "Cr2O7^2– + 14H^+ + 6Fe^2+ → 2Cr^3+ + 6Fe^3+ + 7H2O","exc": false,"tab": false,"src": "d","page": 18,"o": "Cr2O7^2– + 14H^+ + 6Fe^2+ → 2Cr^3+ + 6Fe^3+ + 7H2O"},{"sec": "Potassium permanganate","ids": [253],"t": "KMnO4: fuse MnO2 with alkali hydroxide + oxidant (KNO3) → dark green K2MnO4, which disproportionates in neutral or acid → MnO4^–.","exc": false,"tab": false,"src": "d","page": 18,"o": "Potassium permanganate is prepared by fusion of MnO2 with an alkali metal hydroxide and an oxidising agent like KNO3. This produces the dark green K2MnO4 which disproportionates in a neutral or acidic solution to give permanganate."},{"sec": "Potassium permanganate","ids": [253],"t": "2MnO2 + 4KOH + O2 → 2K2MnO4 + 2H2O; 3MnO4^2– + 4H^+ → 2MnO4^– + MnO2 + 2H2O","exc": false,"tab": false,"src": "d","page": 18,"o": "2MnO2 + 4KOH + O2 → 2K2MnO4 + 2H2O; 3MnO4^2– + 4H^+ → 2MnO4^– + MnO2 + 2H2O"},{"sec": "Potassium permanganate","ids": [253],"t": "Commercial: alkaline oxidative fusion of MnO2, then electrolytic oxidation of manganate(VI).","exc": false,"tab": false,"src": "d","page": 18,"o": "Commercially it is prepared by the alkaline oxidative fusion of MnO2 followed by the electrolytic oxidation of manganate (VI)."},{"sec": "Potassium permanganate","ids": [254],"t": "MnO2 fused with KOH, oxidised with air or KNO3 → MnO4^2- (manganate ion); MnO4^2- → MnO4^- (electrolytic oxidation in alkaline solution).","exc": false,"tab": true,"src": "d","page": 18,"o": "MnO2 fused with KOH, oxidised with air or KNO3 → MnO4^2- (manganate ion); MnO4^2- → MnO4^- (electrolytic oxidation in alkaline solution)."},{"sec": "Potassium permanganate","ids": [255],"t": "Lab: Mn^2+ oxidised by peroxodisulphate: 2Mn^2+ + 5S2O8^2– + 8H2O → 2MnO4^– + 10SO4^2– + 16H^+","exc": false,"tab": false,"src": "d","page": 19,"o": "In the laboratory, a manganese (II) ion salt is oxidised by peroxodisulphate to permanganate. 2Mn^2+ + 5S2O8^2– + 8H2O → 2MnO4^– + 10SO4^2– + 16H^+"},{"sec": "Potassium permanganate","ids": [255],"t": "**KMnO4: dark purple (almost black) crystals, isostructural with KClO4.**","exc": false,"tab": false,"src": "d","page": 19,"o": "Potassium permanganate forms dark purple (almost black) crystals which are isostructural with those of KClO4."},{"sec": "Potassium permanganate","ids": [255],"t": "Sparingly soluble (6.4 g/100 g water, 293 K); **decomposes at 513 K:** 2KMnO4 → K2MnO4 + MnO2 + O2","exc": false,"tab": false,"src": "d","page": 19,"o": "The salt is not very soluble in water (6.4 g/100 g of water at 293 K), but when heated it decomposes at 513 K. 2KMnO4 → K2MnO4 + MnO2 + O2"},{"sec": "Potassium permanganate","ids": [255],"t": "Intense colour; diamagnetic with temperature-dependent weak paramagnetism.","exc": false,"tab": false,"src": "d","page": 19,"o": "It has two physical properties of considerable interest: its intense colour and its diamagnetism along with temperature-dependent weak paramagnetism."},{"sec": "Potassium permanganate","ids": [257],"t": "**Manganate and permanganate tetrahedral; π bonding is O p → Mn d overlap.**","exc": false,"tab": false,"src": "d","page": 19,"o": "The manganate and permanganate ions are tetrahedral; the π-bonding takes place by overlap of p orbitals of oxygen with d orbitals of manganese."},{"sec": "Potassium permanganate","ids": [258],"t": "**Green manganate paramagnetic (one unpaired e^–); permanganate diamagnetic.**","exc": false,"tab": false,"src": "d","page": 19,"o": "The green manganate is paramagnetic because of one unpaired electron but the permanganate is diamagnetic due to the absence of unpaired electron."},{"sec": "Potassium permanganate","ids": [259],"t": "Acidified MnO4^– oxidises oxalate → CO2, Fe(II) → Fe(III), nitrite → nitrate, I^– → I2.","exc": false,"tab": false,"src": "d","page": 19,"o": "Acidified permanganate solution oxidises oxalates to carbon dioxide, iron(II) to iron(III), nitrites to nitrates and iodides to free iodine."},{"sec": "Potassium permanganate","ids": [260],"t": "Half-reactions of reductants: 5C2O4^2- → 10CO2 + 10e^-; 5Fe^2+ → 5Fe^3+ + 5e^-; 5NO2^- + 5H2O → 5NO3^- + 10H^+ + 10e^-; 10I^- → 5I2 + 10e^-","exc": false,"tab": true,"src": "d","page": 19,"o": "Half-reactions of reductants: 5C2O4^2- → 10CO2 + 10e^-; 5Fe^2+ → 5Fe^3+ + 5e^-; 5NO2^- + 5H2O → 5NO3^- + 10H^+ + 10e^-; 10I^- → 5I2 + 10e^-"},{"sec": "Potassium permanganate","ids": [261],"t": "MnO4^– + e^– → MnO4^2– (E° = +0.56 V); MnO4^– + 4H^+ + 3e^– → MnO2 + 2H2O (E° = +1.69 V); MnO4^– + 8H^+ + 5e^– → Mn^2+ + 4H2O (E° = +1.52 V)","exc": false,"tab": false,"src": "d","page": 19,"o": "MnO4^– + e^– → MnO4^2– (E° = +0.56 V); MnO4^– + 4H^+ + 3e^– → MnO2 + 2H2O (E° = +1.69 V); MnO4^– + 8H^+ + 5e^– → Mn^2+ + 4H2O (E° = +1.52 V)"},{"sec": "Potassium permanganate","ids": [261],"t": "[H^+] decides which reduction happens.","exc": false,"tab": false,"src": "d","page": 19,"o": "We can very well see that the hydrogen ion concentration of the solution plays an important part in influencing the reaction."},{"sec": "Potassium permanganate","ids": [262],"t": "Kinetics matters too, not just redox potential.","exc": false,"tab": false,"src": "d","page": 19,"o": "Although many reactions can be understood by consideration of redox potential, kinetics of the reaction is also an important factor."},{"sec": "Potassium permanganate","ids": [263],"t": "**At [H^+] = 1, MnO4^– should oxidise water, but it's extremely slow unless Mn^2+ is present or it's heated.**","exc": true,"tab": false,"src": "d","page": 19,"o": "Permanganate at [H^+] = 1 should oxidise water but in practice the reaction is extremely slow unless either manganese(II) ions are present or the temperature is raised."},{"sec": "Potassium permanganate","ids": [265],"t": "Acid: 10I^– + 2MnO4^– + 16H^+ → 2Mn^2+ + 8H2O + 5I2","exc": false,"tab": false,"src": "d","page": 19,"o": "In acid solutions: (a) Iodine is liberated from potassium iodide: 10I^– + 2MnO4^– + 16H^+ → 2Mn^2+ + 8H2O + 5I2"},{"sec": "Potassium permanganate","ids": [265],"t": "Acid: Fe^2+ (green) → Fe^3+ (yellow): 5Fe^2+ + MnO4^– + 8H^+ → Mn^2+ + 4H2O + 5Fe^3+","exc": false,"tab": false,"src": "d","page": 19,"o": "(b) Fe^2+ ion (green) is converted to Fe^3+ (yellow): 5Fe^2+ + MnO4^– + 8H^+ → Mn^2+ + 4H2O + 5Fe^3+"},{"sec": "Potassium permanganate","ids": [266],"t": "Acid, oxalate at 333 K: 5C2O4^2– + 2MnO4^– + 16H^+ → 2Mn^2+ + 8H2O + 10CO2","exc": false,"tab": false,"src": "d","page": 20,"o": "(c) Oxalate ion or oxalic acid is oxidised at 333 K: 5C2O4^2– + 2MnO4^– + 16H^+ → 2Mn^2+ + 8H2O + 10CO2"},{"sec": "Potassium permanganate","ids": [266],"t": "Acid, H2S → S precipitated: 5S^2– + 2MnO4^– + 16H^+ → 2Mn^2+ + 8H2O + 5S","exc": false,"tab": false,"src": "d","page": 20,"o": "(d) Hydrogen sulphide is oxidised, sulphur being precipitated: 5S^2– + 2MnO4^– + 16H^+ → 2Mn^2+ + 8H2O + 5S"},{"sec": "Potassium permanganate","ids": [266],"t": "Acid, sulphite → sulphate: 5SO3^2– + 2MnO4^– + 6H^+ → 2Mn^2+ + 3H2O + 5SO4^2–","exc": false,"tab": false,"src": "d","page": 20,"o": "(e) Sulphurous acid or sulphite is oxidised to a sulphate or sulphuric acid: 5SO3^2– + 2MnO4^– + 6H^+ → 2Mn^2+ + 3H2O + 5SO4^2–"},{"sec": "Potassium permanganate","ids": [266],"t": "Acid, nitrite → nitrate: 5NO2^– + 2MnO4^– + 6H^+ → 2Mn^2+ + 5NO3^– + 3H2O","exc": false,"tab": false,"src": "d","page": 20,"o": "(f) Nitrite is oxidised to nitrate: 5NO2^– + 2MnO4^– + 6H^+ → 2Mn^2+ + 5NO3^– + 3H2O"},{"sec": "Potassium permanganate","ids": [267],"t": "**Neutral / faintly alkaline: I^– → iodate (not I2):** 2MnO4^– + H2O + I^– → 2MnO2 + 2OH^– + IO3^–","exc": false,"tab": false,"src": "d","page": 20,"o": "In neutral or faintly alkaline solutions: (a) A notable reaction is the oxidation of iodide to iodate: 2MnO4^– + H2O + I^– → 2MnO2 + 2OH^– + IO3^–"},{"sec": "Potassium permanganate","ids": [267],"t": "Neutral: thiosulphate → sulphate almost quantitatively: 8MnO4^– + 3S2O3^2– + H2O → 8MnO2 + 6SO4^2– + 2OH^–","exc": false,"tab": false,"src": "d","page": 20,"o": "(b) Thiosulphate is oxidised almost quantitatively to sulphate: 8MnO4^– + 3S2O3^2– + H2O → 8MnO2 + 6SO4^2– + 2OH^–"},{"sec": "Potassium permanganate","ids": [267],"t": "Neutral: Mn^2+ → MnO2, catalysed by ZnSO4 or ZnO: 2MnO4^– + 3Mn^2+ + 2H2O → 5MnO2 + 4H^+","exc": false,"tab": false,"src": "d","page": 20,"o": "(c) Manganous salt is oxidised to MnO2; the presence of zinc sulphate or zinc oxide catalyses the oxidation: 2MnO4^– + 3Mn^2+ + 2H2O → 5MnO2 + 4H^+"},{"sec": "Potassium permanganate","ids": [267],"t": "**Permanganate titrations in HCl are unsatisfactory: HCl is oxidised to Cl2.**","exc": true,"tab": false,"src": "d","page": 20,"o": "Note: Permanganate titrations in presence of hydrochloric acid are unsatisfactory since hydrochloric acid is oxidised to chlorine."},{"sec": "Potassium permanganate","ids": [268,269],"t": "KMnO4 uses: analysis, preparative organic oxidant, bleaching wool, cotton, silk and other fibres, decolourising oils.","exc": false,"tab": false,"src": "d","page": 20,"o": "Besides its use in analytical chemistry, potassium permanganate is used as a favourite oxidant in preparative organic chemistry. Its uses for the bleaching of wool, cotton, silk and other textile fibres and for the decolourisation of oils are also dependent on its strong oxidising power."},{"sec": "Potassium permanganate","ids": [391],"t": "Pyrolusite (MnO2) is the raw material for KMnO4.","exc": false,"tab": false,"src": "d","page": 26,"o": "Pyrolusite ore (MnO2) is used for the preparation of potassium permanganate."},{"sec": "Applications","ids": [360],"t": "TiO for pigments; MnO2 for dry cells.","exc": false,"tab": false,"src": "d","page": 25,"o": "Some compounds are manufactured for special purposes such as TiO for the pigment industry and MnO2 for use in dry battery cells."},{"sec": "Applications","ids": [361],"t": "Batteries also need Zn and Ni/Cd.","exc": false,"tab": false,"src": "d","page": 25,"o": "The battery industry also requires Zn and Ni/Cd."},{"sec": "Applications","ids": [366],"t": "Many metals and compounds are essential industrial catalysts.","exc": false,"tab": false,"src": "d","page": 26,"o": "Many of the metals and/or their compounds are essential catalysts in the chemical industry."},{"sec": "Applications","ids": [367],"t": "V2O5: SO2 oxidation in H2SO4 manufacture.","exc": false,"tab": false,"src": "d","page": 26,"o": "V2O5 catalyses the oxidation of SO2 in the manufacture of sulphuric acid."},{"sec": "Applications","ids": [368],"t": "**Ziegler catalyst: TiCl4 + Al(CH3)3** for polythene.","exc": false,"tab": false,"src": "d","page": 26,"o": "TiCl4 with Al(CH3)3 forms the basis of the Ziegler catalysts used to manufacture polyethylene (polythene)."},{"sec": "Applications","ids": [369,370],"t": "Fe catalyst: Haber (NH3 from N2/H2). Ni catalyst: hydrogenation of fats.","exc": false,"tab": false,"src": "d","page": 26,"o": "Iron catalysts are used in the Haber process for the production of ammonia from N2/H2 mixtures. Nickel catalysts enable the hydrogenation of fats to proceed."},{"sec": "Applications","ids": [371],"t": "**Wacker: PdCl2 catalyses ethyne → ethanal.** Ni complexes: polymerisation of alkynes and organics such as benzene.","exc": false,"tab": false,"src": "d","page": 26,"o": "In the Wacker process the oxidation of ethyne to ethanal is catalysed by PdCl2. Nickel complexes are useful in the polymerisation of alkynes and other organic compounds such as benzene."},{"sec": "Applications","ids": [372],"t": "AgBr: light-sensitive, photography.","exc": false,"tab": false,"src": "d","page": 26,"o": "The photographic industry relies on the special light-sensitive properties of AgBr."}]);
})();
